@namespace ghidra.graph.viewer.@event.mouse;




using docking;
using edu.uci.ics.jung.visualization.control;
using ghidra.graph.viewer;

public class VisualGraphScreenPositioningPlugin<V, E> : AbstractGraphMousePlugin, MouseWheelListener, VisualGraphMousePlugin<V, E> where V : VisualVertex where E : VisualEdge<V> {

	public VisualGraphScreenPositioningPlugin() : base(0)
    {
	}

	/* @Override */
	public bool checkModifiers(MouseEvent e) {
		return e.getModifiersEx() == modifiers;
	}

	/* @Override */
	public void mouseWheelMoved(MouseWheelEvent e) {
		int eventModifiers = e.getModifiersEx();
		bool controlKeyDown = (eventModifiers & DockingUtils.CONTROL_KEY_MODIFIER_MASK) != 0;
		if (!controlKeyDown) {
			return;
		}

		int wheelRotation = -e.getWheelRotation();
		int offset = wheelRotation * 10;

		Point newPoint = new Point(0, offset);

		if (e.isAltDown()) {
			// control-alt is a horizontal pan
			newPoint.setLocation(offset, 0);
		}

		VisualGraphViewUpdater<V, E> updater = getViewUpdater(e);
		updater.moveViewerLocationWithoutAnimation(newPoint);
	}
}
